"""Regression tests for the TimesFM-2 forecaster."""

import numpy as np
import pytest

from sktime.datasets import load_airline
from sktime.forecasting.timesfm2 import TimesFM2Forecaster
from sktime.tests.test_switch import run_test_for_class

# Reference forecasts were generated by calling the corresponding transformers
# model class directly (bypassing sktime), e.g. for the 2.5 checkpoint:
#
#   from transformers import TimesFm2_5ModelForPrediction
#   import numpy as np, torch
#   from sktime.datasets import load_airline
#
#   y_train = load_airline().iloc[:-12]
#   model = TimesFm2_5ModelForPrediction.from_pretrained(
#       "google/timesfm-2.5-200m-transformers", device_map="cpu", dtype=None
#   )
#   model.eval()
#   past_values = torch.from_numpy(
#       np.expand_dims(y_train.values.astype(np.float32), axis=0)
#   ).to(model.dtype).to(model.device)
#   with torch.no_grad():
#       output = model(past_values=past_values)
#   preds = output.mean_predictions.ravel().detach().float().cpu().numpy()
#   preds[:3]  # -> [407.3865051269531, 378.2121887207031, 429.0090026855469]
#
# For the 2.0 checkpoint, replace the import/model_path with
# ``transformers.TimesFmModelForPrediction`` / "google/timesfm-2.0-500m-pytorch"
# (a different model class, exercising a different code path in
# TimesFM2Forecaster's config/model resolution).
_TIMESFM2_REFERENCE_CASES = [
    pytest.param(
        "google/timesfm-2.5-200m-transformers",
        [407.3865051269531, 378.2121887207031, 429.0090026855469],
        id="timesfm-2.5-200m-transformers",
    ),
    pytest.param(
        "google/timesfm-2.0-500m-pytorch",
        [417.9764404296875, 410.7521667480469, 444.2551574707031],
        id="timesfm-2.0-500m-pytorch",
    ),
]


@pytest.mark.skipif(
    not run_test_for_class(TimesFM2Forecaster),
    reason="run test only if softdeps are present and incrementally (if requested)",
)
@pytest.mark.parametrize("model_path,expected_head", _TIMESFM2_REFERENCE_CASES)
def test_timesfm2_airline_predictions_match_transformers_reference(
    model_path, expected_head
):
    """TimesFM-2 predictions match the raw transformers implementation."""
    y = load_airline()
    y_train = y.iloc[:-12]
    fh = np.arange(1, 13)

    forecaster = TimesFM2Forecaster(model_path=model_path, device_map="cpu")
    y_pred = forecaster.fit(y_train, fh=fh).predict(fh=fh)

    np.testing.assert_allclose(
        y_pred.iloc[:3].to_numpy(),
        np.asarray(expected_head, dtype=np.float32),
        rtol=1e-5,
        atol=1e-4,
    )
